test.userScript:
function test(expression) {
  try {
    var value = Function('return ' + expression)();
    if (value === window) {
      addSuccess(expression, 'resolves to window');
    } else {
      addInfo(expression, Object.prototype.toString.call(value));
    }
  } catch (error) {
    addError(expression, error.name + ': ' + error.message);
  }
}

function test(field) {
  var event = new MessageEvent('message', {
    data: 'payload',
    origin: location.origin,
    source: window
  });
  var before = event[field];
  var writable = true;
  try {
    event[field] = 'dom-lab';
  } catch (error) {
    writable = false;
  }
  var descriptor = Object.getOwnPropertyDescriptor(MessageEvent.prototype, field);
  addInfo(field, JSON.stringify({ before: String(before), after: String(event[field]), writable: writable, configurable: !!(descriptor && descriptor.configurable) }));
}

function test(api) {
  try {
    if (!(api in window)) {
      addInfo(api, 'not exposed');
      return;
    }
    if (api === 'localStorage' || api === 'sessionStorage') {
      window[api].setItem('__dom_lab_probe__', '1');
      window[api].removeItem('__dom_lab_probe__');
      addSuccess(api, 'read/write available');
      return;
    }
    addInfo(api, Object.prototype.toString.call(window[api]));
  } catch (error) {
    addError(api, error.name + ': ' + error.message);
  }
}

function test(payload) {
  try {
    var doc = new DOMParser().parseFromString(payload, 'text/html');
    var first = doc.body.firstElementChild;
    addInfo(payload, first ? first.tagName.toLowerCase() + ' / ' + doc.body.childElementCount + ' node(s)' : 'empty body');
  } catch (error) {
    addError(payload, error.name + ': ' + error.message);
  }
}
